                    row.setBackground(ColorScheme.DARKER_GRAY_COLOR); row.repaint();
                }
            };
            row.addMouseListener(handler);
            nameLabel.addMouseListener(handler);
        } else {
            nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
