package com.osr.jei.service;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.osr.jei.model.DropEntry;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.net.URLEncoder;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Fetches drop-table data from the OSRS Wiki.
 *
 * Strategy:
 *  1. GET action=parse&prop=sections to find which section index holds "Item sources".
 *  2. GET action=parse&prop=text&section=N to retrieve the rendered HTML for that section.
 *  3. Locate the table whose class includes "item-drops" and parse each <tr>.
 *
 * Results are cached per item name. Network errors are NOT cached.
 */
@Slf4j
@Singleton
public class WikiService {

    private static final String WIKI_API   = "https://oldschool.runescape.wiki/api.php";
    private static final String USER_AGENT = "OSRS-JEI-RuneLite-Plugin/1.0";

    @Inject private OkHttpClient okHttpClient;

    private final ConcurrentHashMap<String, List<DropEntry>> dropCache = new ConcurrentHashMap<>();

    // ── Public API ─────────────────────────────────────────────────────────────

    @SuppressWarnings("deprecation")
    public List<DropEntry> getDropSources(String itemName) {
        if (dropCache.containsKey(itemName)) return dropCache.get(itemName);

        List<DropEntry> drops = new ArrayList<>();
        try {
            String encoded = URLEncoder.encode(itemName.replace(" ", "_"), "UTF-8");

            int sectionIndex = findItemSourcesSection(encoded);
            if (sectionIndex < 0) {
                log.info("[JEI] No 'Item sources' section for '{}'", itemName);
                dropCache.put(itemName, drops);
                return drops;
            }

            String textUrl = WIKI_API
                + "?action=parse&prop=text&format=json&section=" + sectionIndex
                + "&page=" + encoded;

            JsonObject textRoot = fetchJson(textUrl);
            if (textRoot == null || !textRoot.has("parse")) {
                dropCache.put(itemName, drops);
                return drops;
            }

            String html = textRoot.getAsJsonObject("parse")
                .getAsJsonObject("text")
                .get("*").getAsString();

            drops = parseItemDropsTable(html);
            log.info("[JEI] Drops for '{}': {} entries", itemName, drops.size());
            dropCache.put(itemName, drops);

        } catch (Exception e) {
            log.warn("[JEI] Failed to fetch drops for '{}': {}", itemName, e.getMessage());
        }
        return drops;
    }

    // ── Section finder ─────────────────────────────────────────────────────────

    @SuppressWarnings("deprecation")
    private int findItemSourcesSection(String encodedName) throws Exception {
        String url = WIKI_API
            + "?action=parse&prop=sections&format=json&redirects=true&page=" + encodedName;

        JsonObject root = fetchJson(url);
        if (root == null || !root.has("parse")) return -1;

        JsonArray sections = root.getAsJsonObject("parse").getAsJsonArray("sections");
        if (sections == null) return -1;

        for (JsonElement el : sections) {
            JsonObject sec   = el.getAsJsonObject();
            String title = stripHtml(sec.get("line").getAsString()).toLowerCase();
            if (title.equals("item sources") || title.equals("sources")
                    || title.equals("drop sources") || title.equals("drops")) {
                return Integer.parseInt(sec.get("index").getAsString());
            }
        }
        return -1;
    }

    // ── HTML table parser ──────────────────────────────────────────────────────

    private List<DropEntry> parseItemDropsTable(String html) {
        List<DropEntry> drops = new ArrayList<>();

        int markerIdx = html.indexOf("item-drops");
        if (markerIdx < 0) {
            log.debug("[JEI] No item-drops table found in section HTML");
            return drops;
        }

        int tStart = html.lastIndexOf("<table", markerIdx);
        if (tStart < 0) return drops;
        int tEnd = html.indexOf("</table>", markerIdx);
        if (tEnd < 0) return drops;
        String table = html.substring(tStart, tEnd + 8);

        int tbodyStart = table.indexOf("<tbody>");
        if (tbodyStart >= 0) {
            int tbodyEnd = table.indexOf("</tbody>", tbodyStart);
            table = tbodyEnd >= 0
                ? table.substring(tbodyStart, tbodyEnd + 8)
                : table.substring(tbodyStart);
        }

        int pos = 0;
        while (true) {
            int rowStart = table.indexOf("<tr", pos);
            if (rowStart < 0) break;
            int rowEnd = table.indexOf("</tr>", rowStart);
            if (rowEnd < 0) break;
            String row = table.substring(rowStart, rowEnd + 5);
            pos = rowEnd + 5;

            if (!row.contains("<td")) continue;

            List<String> cells = extractCells(row);
            if (cells.size() < 3) continue;

            String source   = stripHtml(cells.get(0));
            String level    = stripHtml(cells.size() > 1 ? cells.get(1) : "");
            String quantity = stripHtml(cells.size() > 2 ? cells.get(2) : "");
            String rate     = stripHtml(cells.size() > 3 ? cells.get(3) : "");

            if (source.isEmpty()) continue;

            DropEntry drop = new DropEntry();
            drop.setSource(source);
            drop.setLevel(level);
            drop.setQuantity(quantity.isEmpty() ? "?" : quantity);
            drop.setRate(rate);
            drop.setRarity("");
            drops.add(drop);
        }
        return drops;
    }

    // ── HTML utilities ─────────────────────────────────────────────────────────

    private List<String> extractCells(String row) {
        List<String> cells = new ArrayList<>();
        int pos = 0;
        while (true) {
            int start   = row.indexOf("<td", pos);
            if (start < 0) break;
            int closeGt = row.indexOf(">", start);
            if (closeGt < 0) break;
            int end     = row.indexOf("</td>", closeGt);
            if (end < 0) break;
            cells.add(row.substring(closeGt + 1, end));
            pos = end + 5;
        }
        return cells;
    }

    private String stripHtml(String html) {
        if (html == null || html.isEmpty()) return "";
        String text = html.replaceAll("<[^>]+>", "");
        text = text.replace("&amp;",  "&")
                   .replace("&lt;",   "<")
                   .replace("&gt;",   ">")
                   .replace("&nbsp;", " ")
                   .replace("&#160;", " ")
                   .replace("&ndash;","–")
                   .replace("&mdash;","—");
        return text.trim().replaceAll("\\s+", " ");
    }

    // ── Network ────────────────────────────────────────────────────────────────

    private JsonObject fetchJson(String urlStr) {
        try {
            Request request = new Request.Builder()
                .url(urlStr)
                .header("User-Agent", USER_AGENT)
                .build();

            try (Response response = okHttpClient.newCall(request).execute()) {
                if (!response.isSuccessful() || response.body() == null) {
                    log.warn("[JEI] HTTP {} for {}", response.code(), urlStr);
                    return null;
                }
                return new JsonParser().parse(response.body().string()).getAsJsonObject();
            }
        } catch (Exception e) {
            log.warn("[JEI] Request failed: {}", e.getMessage());
            return null;
        }
    }
}

package com.osr.jei.service;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.net.URLEncoder;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Finds every item that can be crafted using a given ingredient by parsing the
 * "Products" section that the OSRS Wiki maintains on each ingredient's own page.
 */
@Slf4j
@Singleton
public class UsedInService {

    private static final String WIKI_API   = "https://oldschool.runescape.wiki/api.php";
    private static final String USER_AGENT = "osrs-jei-plugin";

    @Inject private OkHttpClient okHttpClient;

    private final ConcurrentHashMap<String, List<String>> cache = new ConcurrentHashMap<>();

    // ── Public API ─────────────────────────────────────────────────────────────

    @SuppressWarnings("deprecation")
    public List<String> getCandidateProducts(String ingredientName) {
        String key = ingredientName.toLowerCase(Locale.ROOT);
        List<String> cached = cache.get(key);
        if (cached != null) return cached;

        try {
            List<String> result = fetchProducts(ingredientName);
            cache.put(key, result);
            return result;
        } catch (Exception e) {
            log.warn("[JEI] UsedIn fetch failed for '{}': {}", ingredientName, e.getMessage());
            return Collections.emptyList();
        }
    }

    // ── Fetch ──────────────────────────────────────────────────────────────────

    @SuppressWarnings("deprecation")
    private List<String> fetchProducts(String ingredientName) throws Exception {
        String encoded = URLEncoder.encode(ingredientName.replace(" ", "_"), "UTF-8");

        int sectionIndex = findProductsSection(encoded);
        if (sectionIndex < 0) {
            log.info("[JEI] No Products section for '{}'", ingredientName);
            return Collections.emptyList();
        }

        String html = fetchSectionHtml(encoded, sectionIndex);
        if (html.isEmpty()) return Collections.emptyList();

        List<String> products = parseProductsTable(html);
        log.debug("[JEI] Products for '{}': {} item(s)", ingredientName, products.size());
        return products;
    }

    // ── Section finder ─────────────────────────────────────────────────────────

    private int findProductsSection(String encodedName) throws Exception {
        JsonObject root = fetchJson(WIKI_API
            + "?action=parse&prop=sections&format=json&redirects=true&page=" + encodedName);
        if (root == null || !root.has("parse")) return -1;

        JsonArray sections = root.getAsJsonObject("parse").getAsJsonArray("sections");
        if (sections == null) return -1;

        for (JsonElement el : sections) {
            JsonObject sec = el.getAsJsonObject();
            String title = stripHtml(sec.get("line").getAsString())
                .toLowerCase(Locale.ROOT).trim();
            if (title.equals("products")
                    || title.equals("uses")
                    || title.equals("items created")
                    || title.equals("created from")) {
                return Integer.parseInt(sec.get("index").getAsString());
            }
        }
        return -1;
    }

    private String fetchSectionHtml(String encodedName, int sectionIdx) throws Exception {
        JsonObject root = fetchJson(WIKI_API
            + "?action=parse&prop=text&format=json&section=" + sectionIdx
            + "&page=" + encodedName);
        if (root == null || !root.has("parse")) return "";
        return root.getAsJsonObject("parse").getAsJsonObject("text").get("*").getAsString();
    }

    // ── HTML table parser ──────────────────────────────────────────────────────

    private static final Pattern ITEM_HREF =
        Pattern.compile("href=\"/w/([^\"#:]+)\"");

    private List<String> parseProductsTable(String html) {
        Set<String> seen = new LinkedHashSet<>();

        int markerIdx = html.indexOf("wikitable");
        if (markerIdx < 0) return new ArrayList<>();
        int tableStart = html.lastIndexOf("<table", markerIdx);
        if (tableStart < 0) return new ArrayList<>();
        int tableEnd = html.indexOf("</table>", markerIdx);
        if (tableEnd < 0) return new ArrayList<>();
        String table = html.substring(tableStart, tableEnd + 8);

        int tbodyStart = table.indexOf("<tbody>");
        if (tbodyStart >= 0) {
            int tbodyEnd = table.indexOf("</tbody>", tbodyStart);
            table = tbodyEnd >= 0
                ? table.substring(tbodyStart, tbodyEnd + 8)
                : table.substring(tbodyStart);
        }

        int pos = 0;
        while (true) {
            int rowStart = table.indexOf("<tr", pos);
            if (rowStart < 0) break;
            int rowEnd = table.indexOf("</tr>", rowStart);
            if (rowEnd < 0) break;
            String row = table.substring(rowStart, rowEnd + 5);
            pos = rowEnd + 5;

            if (!row.contains("<td")) continue;

            Matcher m = ITEM_HREF.matcher(row);
            if (m.find()) {
                String pageName = m.group(1).replace("_", " ");
                if (!pageName.isEmpty()) seen.add(pageName);
            }
        }

        return new ArrayList<>(seen);
    }

    // ── Network ────────────────────────────────────────────────────────────────

    private JsonObject fetchJson(String urlStr) throws Exception {
        Request request = new Request.Builder()
            .url(urlStr)
            .header("User-Agent", USER_AGENT)
            .build();

        try (Response response = okHttpClient.newCall(request).execute()) {
            if (!response.isSuccessful() || response.body() == null) {
                log.warn("[JEI] HTTP {} for {}", response.code(), urlStr);
                return null;
            }
            return new JsonParser().parse(response.body().string()).getAsJsonObject();
        }
    }

    // ── Utilities ──────────────────────────────────────────────────────────────

    private String stripHtml(String html) {
        if (html == null || html.isEmpty()) return "";
        return html.replaceAll("<[^>]+>", "").trim();
    }
}

package com.osr.jei.service;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.osr.jei.model.ShopEntry;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.net.URLEncoder;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Finds every shop that sells a given item by parsing the "Shop locations"
 * section on the item's OSRS Wiki page.
 */
@Slf4j
@Singleton
public class ShopService {

    private static final String WIKI_API   = "https://oldschool.runescape.wiki/api.php";
    private static final String USER_AGENT = "osrs-jei-plugin";

    @Inject private OkHttpClient okHttpClient;

    private final ConcurrentHashMap<String, List<ShopEntry>> cache =
        new ConcurrentHashMap<>();

    // ── Public API ─────────────────────────────────────────────────────────────

    public List<ShopEntry> getShops(String itemName) {
        String key = itemName.toLowerCase(Locale.ROOT);
        List<ShopEntry> cached = cache.get(key);
        if (cached != null) return cached;

        try {
            List<ShopEntry> result = fetchShops(itemName);
            cache.put(key, result);
            log.debug("[JEI] ShopService '{}': {} shop(s)", itemName, result.size());
            return result;
        } catch (Exception e) {
            log.warn("[JEI] ShopService failed for '{}': {}", itemName, e.getMessage());
            return Collections.emptyList();
        }
    }

    // ── Fetch ──────────────────────────────────────────────────────────────────

    @SuppressWarnings("deprecation")
    private List<ShopEntry> fetchShops(String itemName) throws Exception {
        String encoded = URLEncoder.encode(itemName.replace(" ", "_"), "UTF-8");

        int sectionIndex = findShopSection(encoded);
        if (sectionIndex < 0) {
            log.info("[JEI] No shop-locations section for '{}'", itemName);
            return Collections.emptyList();
        }

        String html = fetchSectionHtml(encoded, sectionIndex);
        if (html.isEmpty()) return Collections.emptyList();

        return parseShopTable(html);
    }

    // ── Section finder ─────────────────────────────────────────────────────────

    private int findShopSection(String encodedName) throws Exception {
        JsonObject root = fetchJson(WIKI_API
            + "?action=parse&prop=sections&format=json&redirects=true&page=" + encodedName);
        if (root == null || !root.has("parse")) return -1;

        JsonArray sections = root.getAsJsonObject("parse").getAsJsonArray("sections");
        if (sections == null) return -1;

        for (JsonElement el : sections) {
            JsonObject sec = el.getAsJsonObject();
            String title = stripHtml(sec.get("line").getAsString())
                .toLowerCase(Locale.ROOT).trim();
            if (title.equals("shop locations")
                    || title.equals("sold by")
                    || title.equals("store locations")
                    || title.equals("availability")
                    || title.equals("shops")) {
                return Integer.parseInt(sec.get("index").getAsString());
            }
        }
        return -1;
    }

    private String fetchSectionHtml(String encodedName, int sectionIdx) throws Exception {
        JsonObject root = fetchJson(WIKI_API
            + "?action=parse&prop=text&format=json&section=" + sectionIdx
            + "&page=" + encodedName);
        if (root == null || !root.has("parse")) return "";
        return root.getAsJsonObject("parse").getAsJsonObject("text").get("*").getAsString();
    }

    // ── HTML table parser ──────────────────────────────────────────────────────

    private List<ShopEntry> parseShopTable(String html) {
        List<ShopEntry> shops = new ArrayList<>();

        int markerIdx = html.indexOf("store-locations-list");
        if (markerIdx < 0) markerIdx = html.indexOf("wikitable");
        if (markerIdx < 0) return shops;

        int tableStart = html.lastIndexOf("<table", markerIdx);
        if (tableStart < 0) return shops;
        int tableEnd = html.indexOf("</table>", markerIdx);
        if (tableEnd < 0) return shops;
        String table = html.substring(tableStart, tableEnd + 8);

        int sellerCol = 0;
        int priceCol  = -1;
        int stockCol  = -1;

        int pos = 0;
        boolean headerFound = false;
        while (!headerFound) {
            int rowStart = table.indexOf("<tr", pos);
            if (rowStart < 0) break;
            int rowEnd = table.indexOf("</tr>", rowStart);
            if (rowEnd < 0) break;
            String row = table.substring(rowStart, rowEnd + 5);
            pos = rowEnd + 5;

            if (!row.contains("<th")) continue;
            headerFound = true;

            List<String> ths = extractCells(row, "th");
            for (int i = 0; i < ths.size(); i++) {
                String h = stripHtml(ths.get(i)).toLowerCase(Locale.ROOT).trim();
                if (h.contains("seller") || h.contains("store") || h.contains("shop")) sellerCol = i;
                if (h.contains("sold"))  priceCol = i;
                if (h.contains("stock")) stockCol = i;
            }
        }

        while (true) {
            int rowStart = table.indexOf("<tr", pos);
            if (rowStart < 0) break;
            int rowEnd = table.indexOf("</tr>", rowStart);
            if (rowEnd < 0) break;
            String row = table.substring(rowStart, rowEnd + 5);
            pos = rowEnd + 5;

            if (!row.contains("<td")) continue;

            List<String> cells = extractCells(row, "td");
            if (cells.isEmpty()) continue;

            String shopName = "";
            if (sellerCol < cells.size()) {
                shopName = extractLinkText(cells.get(sellerCol));
                if (shopName.isEmpty()) shopName = stripHtml(cells.get(sellerCol));
            }
            if (shopName.isEmpty() || shopName.equalsIgnoreCase("n/a")) continue;

            int price = 0;
            if (priceCol >= 0 && priceCol < cells.size()) {
                price = sortableInt(cells.get(priceCol));
            }

            int stock = 0;
            if (stockCol >= 0 && stockCol < cells.size()) {
                stock = sortableInt(cells.get(stockCol));
            }

            shops.add(new ShopEntry(shopName, price, stock));
        }

        return shops;
    }

    // ── HTML utilities ─────────────────────────────────────────────────────────

    private List<String> extractCells(String row, String tag) {
        List<String> cells = new ArrayList<>();
        String openTag  = "<" + tag;
        String closeTag = "</" + tag + ">";
        int pos = 0;
        while (true) {
            int start = row.indexOf(openTag, pos);
            if (start < 0) break;
            int end = row.indexOf(closeTag, start);
            if (end < 0) break;
            cells.add(row.substring(start, end + closeTag.length()));
            pos = end + closeTag.length();
        }
        return cells;
    }

    private String extractLinkText(String cell) {
        int aStart = cell.indexOf("<a ");
        if (aStart < 0) aStart = cell.indexOf("<a\n");
        if (aStart < 0) return "";
        int gt = cell.indexOf(">", aStart);
        if (gt < 0) return "";
        int end = cell.indexOf("</a>", gt);
        if (end < 0) return "";
        return stripHtml(cell.substring(gt + 1, end)).trim();
    }

    private static final Pattern DATA_SORT = Pattern.compile("data-sort-value=\"([0-9,]+)\"");
    private static final Pattern ALL_INTS  = Pattern.compile("\\d+");

    private int sortableInt(String cellHtml) {
        Matcher m = DATA_SORT.matcher(cellHtml);
        if (m.find()) {
            try { return Integer.parseInt(m.group(1).replace(",", "")); }
            catch (NumberFormatException ignored) { }
        }
        String text = stripHtml(cellHtml).replace(",", "");
        Matcher dm = ALL_INTS.matcher(text);
        int last = 0;
        while (dm.find()) {
            try { last = Integer.parseInt(dm.group()); }
            catch (NumberFormatException ignored) { }
        }
        return last;
    }

    private String stripHtml(String html) {
        if (html == null || html.isEmpty()) return "";
        String text = html.replaceAll("<[^>]+>", "");
        text = text.replace("&amp;", "&").replace("&lt;", "<")
                   .replace("&gt;", ">").replace("&nbsp;", " ")
                   .replace("&#160;", " ").replace("&ndash;", "–");
        return text.trim().replaceAll("\\s+", " ");
    }

    // ── Network ────────────────────────────────────────────────────────────────

    private JsonObject fetchJson(String urlStr) throws Exception {
        Request request = new Request.Builder()
            .url(urlStr)
            .header("User-Agent", USER_AGENT)
            .build();

        try (Response response = okHttpClient.newCall(request).execute()) {
            if (!response.isSuccessful() || response.body() == null) {
                log.warn("[JEI] HTTP {} for {}", response.code(), urlStr);
                return null;
            }
            return new JsonParser().parse(response.body().string()).getAsJsonObject();
        }
    }
}

package com.osr.jei.service;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.osr.jei.model.RecipeInfo;
import com.osr.jei.model.RecipeIngredient;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.net.URLEncoder;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Fetches crafting recipe data from the OSRS Wiki by requesting the raw wikitext
 * for an item's page and parsing the {{Infobox Recipe}} template block.
 *
 * <p>Wikitext is cached separately from the recipe result so that other services
 * (EquipmentService, ShopService) can call {@link #getWikitext} and get the
 * already-fetched wikitext without making a second network request.
 *
 * <p>Network errors are NOT cached — the next call will retry.
 */
@Slf4j
@Singleton
public class RecipeService {

    private static final String API_BASE =
        "https://oldschool.runescape.wiki/api.php"
        + "?action=parse&prop=wikitext&format=json&redirects=true&page=";
    private static final String USER_AGENT = "osrs-jei-plugin";

    @Inject private OkHttpClient okHttpClient;

    private final ConcurrentHashMap<String, String> wikitextCache =
        new ConcurrentHashMap<>();

    private final ConcurrentHashMap<String, Optional<RecipeInfo>> recipeCache =
        new ConcurrentHashMap<>();

    // ── Public API ─────────────────────────────────────────────────────────────

    public Optional<RecipeInfo> getRecipe(String itemName) {
        String key = itemName.toLowerCase(Locale.ROOT);
        Optional<RecipeInfo> cached = recipeCache.get(key);
        if (cached != null) return cached;

        try {
            String wikitext = ensureWikitext(itemName, key);
            Optional<RecipeInfo> result = wikitext.isEmpty()
                ? Optional.empty()
                : parseWikitext(wikitext);
            recipeCache.put(key, result);
            return result;
        } catch (Exception e) {
            log.warn("[JEI] Recipe fetch failed for '{}': {}", itemName, e.getMessage());
            return Optional.empty();
        }
    }

    public String getWikitext(String itemName) {
        String key = itemName.toLowerCase(Locale.ROOT);
        String cached = wikitextCache.get(key);
        if (cached != null) return cached;

        try {
            return ensureWikitext(itemName, key);
        } catch (Exception e) {
            log.warn("[JEI] Wikitext fetch failed for '{}': {}", itemName, e.getMessage());
            return "";
        }
    }

    // ── Internal helpers ───────────────────────────────────────────────────────

    private String ensureWikitext(String itemName, String key) throws Exception {
        String cached = wikitextCache.get(key);
        if (cached != null) return cached;

        String wikitext = fetchWikitext(itemName);
        wikitextCache.put(key, wikitext);
        return wikitext;
    }

    // ── Network ────────────────────────────────────────────────────────────────

    @SuppressWarnings("deprecation")
    private String fetchWikitext(String itemName) throws Exception {
        String encoded = URLEncoder.encode(itemName.replace(" ", "_"), "UTF-8");

        Request request = new Request.Builder()
            .url(API_BASE + encoded)
            .header("User-Agent", USER_AGENT)
            .build();

        try (Response response = okHttpClient.newCall(request).execute()) {
            if (!response.isSuccessful() || response.body() == null) return "";
            JsonObject root = new JsonParser().parse(response.body().string()).getAsJsonObject();
            if (!root.has("parse")) return "";
            return root.getAsJsonObject("parse")
                .getAsJsonObject("wikitext")
                .get("*").getAsString();
        }
    }

    // ── Wikitext parsing ───────────────────────────────────────────────────────

    private Optional<RecipeInfo> parseWikitext(String wikitext) {
        String lower = wikitext.toLowerCase(Locale.ROOT);
        int startIdx = lower.indexOf("{{recipe\n");
        if (startIdx == -1) startIdx = lower.indexOf("{{recipe|");
        if (startIdx == -1) startIdx = lower.indexOf("{{recipe ");
        if (startIdx == -1) {
            log.info("[JEI] No {{Recipe}} template found in wikitext");
            return Optional.empty();
        }

        String block = extractTemplateBlock(wikitext, startIdx);
        if (block == null) {
            log.warn("[JEI] Found Recipe template start but could not extract block");
            return Optional.empty();
        }

        Map<String, String> p = parseParams(block);
        log.debug("[JEI] Recipe params: {}", p.keySet());

        String skill = clean(coalesce(p, "skill1", "skill2", "skill"));
        int level = firstInt(clean(coalesce(p, "skill1lvl", "skill2lvl", "level", "lvl")));

        String tools      = clean(coalesce(p, "tools", "tool"));
        String facilities = clean(coalesce(p, "facilities", "facility", "location"));
        for (String bad : new String[]{"none", "n/a", "inventory", "no"}) {
            if (tools.equalsIgnoreCase(bad))      tools      = "";
            if (facilities.equalsIgnoreCase(bad)) facilities = "";
        }
        String facility;
        if (!tools.isEmpty() && !facilities.isEmpty()) {
            facility = tools + " + " + facilities;
        } else if (!tools.isEmpty()) {
            facility = tools;
        } else {
            facility = facilities;
        }

        double xp = firstDouble(clean(coalesce(p, "skill1exp", "skill2exp", "experience", "xp")));

        List<RecipeIngredient> ingredients = new ArrayList<>();
        for (int i = 1; i <= 10; i++) {
            String mat = clean(p.getOrDefault("mat" + i, "")).trim();
            if (mat.isEmpty() || mat.equalsIgnoreCase("none")
                    || mat.equalsIgnoreCase("n/a")) break;

            int qty = 1;
            String qtyRaw = clean(p.getOrDefault("mat" + i + "quantity", "1"))
                .replace(",", "").replaceAll("[^0-9].*", "").trim();
            if (!qtyRaw.isEmpty()) {
                try { qty = Integer.parseInt(qtyRaw); } catch (NumberFormatException ignored) {}
            }
            ingredients.add(new RecipeIngredient(mat, qty));
        }

        if (skill.isEmpty() && ingredients.isEmpty()) {
            log.info("[JEI] Recipe template found but no skill/ingredients extracted");
            return Optional.empty();
        }

        log.info("[JEI] Recipe parsed: skill={} lv={} facility='{}' ingredients={}",
            skill, level, facility, ingredients.size());
        return Optional.of(new RecipeInfo(skill, level, facility, xp, ingredients));
    }

    // ── Wikitext template utilities ────────────────────────────────────────────

    private String extractTemplateBlock(String text, int startIdx) {
        int depth = 0;
        int i = startIdx;
        while (i < text.length() - 1) {
            char c    = text.charAt(i);
            char next = text.charAt(i + 1);
            if      (c == '{' && next == '{') { depth++; i += 2; }
            else if (c == '}' && next == '}') {
                depth--;
                if (depth == 0) return text.substring(startIdx, i + 2);
                i += 2;
            } else {
                i++;
            }
        }
        return null;
    }

    private List<String> splitTopLevel(String text) {
        List<String> parts = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (i + 1 < text.length()) {
                char nx = text.charAt(i + 1);
                if ((c == '{' && nx == '{') || (c == '[' && nx == '[')) { depth++; i++; continue; }
                if ((c == '}' && nx == '}') || (c == ']' && nx == ']')) { depth--; i++; continue; }
            }
            if (c == '|' && depth == 0) {
                parts.add(text.substring(start, i));
                start = i + 1;
            }
        }
        parts.add(text.substring(start));
        return parts;
    }

    private Map<String, String> parseParams(String block) {
        String inner = block;
        if (inner.startsWith("{{")) inner = inner.substring(2);
        if (inner.endsWith("}}"))   inner = inner.substring(0, inner.length() - 2);

        Map<String, String> params = new LinkedHashMap<>();
        List<String> parts = splitTopLevel(inner);
        for (int i = 1; i < parts.size(); i++) {
            String part = parts.get(i).replace("\n", " ").trim();
            if (part.isEmpty()) continue;

            int eq = part.indexOf('=');
            if (eq <= 0) continue;
            String key = part.substring(0, eq).trim().toLowerCase(Locale.ROOT);
            String val = part.substring(eq + 1).trim();
            if (!key.isEmpty()) params.put(key, val);
        }
        return params;
    }

    private String coalesce(Map<String, String> params, String... keys) {
        for (String key : keys) {
            String v = params.get(key);
            if (v != null && !v.trim().isEmpty()) return v;
        }
        return "";
    }

    // ── Wiki markup stripping ──────────────────────────────────────────────────

    private static final Pattern WIKILINK  = Pattern.compile("\\[\\[(?:[^|\\]]*\\|)?([^\\]]+)\\]\\]");
    private static final Pattern TEMPLATE1 = Pattern.compile("\\{\\{[^{}|]*\\|([^{}|]*)\\}\\}");
    private static final Pattern TEMPLATE2 = Pattern.compile("\\{\\{[^{}]*\\}\\}");
    private static final Pattern EXTLINK   = Pattern.compile("\\[https?://\\S+\\s([^\\]]+)\\]");
    private static final Pattern HTML_TAG  = Pattern.compile("<[^>]+>");

    private String clean(String text) {
        if (text == null || text.trim().isEmpty()) return "";
        text = WIKILINK.matcher(text).replaceAll("$1");
        text = TEMPLATE1.matcher(text).replaceAll("$1");
        text = TEMPLATE2.matcher(text).replaceAll("");
        text = EXTLINK.matcher(text).replaceAll("$1");
        text = text.replaceAll("'{2,}", "");
        text = text.replace("&amp;", "&").replace("&lt;", "<")
                   .replace("&gt;", ">").replace("&nbsp;", " ").replace("&#160;", " ");
        text = HTML_TAG.matcher(text).replaceAll("");
        return text.replaceAll("\\s+", " ").trim();
    }

    // ── Number helpers ─────────────────────────────────────────────────────────

    private static final Pattern DIGITS  = Pattern.compile("\\d+");
    private static final Pattern DECIMAL = Pattern.compile("[0-9]+(?:\\.[0-9]+)?");

    private int firstInt(String text) {
        if (text == null || text.isEmpty()) return 0;
        Matcher m = DIGITS.matcher(text.replace(",", ""));
        return m.find() ? Integer.parseInt(m.group()) : 0;
    }

    private double firstDouble(String text) {
        if (text == null || text.isEmpty()) return 0;
        Matcher m = DECIMAL.matcher(text.replace(",", ""));
        return m.find() ? Double.parseDouble(m.group()) : 0;
    }
}

package com.osr.jei.service;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Fetches live Grand Exchange prices from the OSRS Wiki prices API.
 * Results are cached so we don't spam the API for the same item.
 */
@Slf4j
@Singleton
public class PriceService {

    private static final String PRICES_API = "https://prices.runescape.wiki/api/v1/osrs/latest";
    private static final String USER_AGENT = "OSRS-JEI-RuneLite-Plugin/1.0 (github contact)";

    @Inject private OkHttpClient okHttpClient;

    // Simple in-memory cache: item ID -> price in gp
    private final ConcurrentHashMap<Integer, Long> cache = new ConcurrentHashMap<>();

    /**
     * Returns the average GE price for the given item ID, or -1 if unavailable.
     * Call this on a background thread — it makes a network request.
     */
    public long getPrice(int itemId) {
        if (cache.containsKey(itemId)) {
            return cache.get(itemId);
        }

        try {
            Request request = new Request.Builder()
                .url(PRICES_API + "?id=" + itemId)
                .header("User-Agent", USER_AGENT)
                .build();

            try (Response response = okHttpClient.newCall(request).execute()) {
                if (!response.isSuccessful() || response.body() == null) return -1;

                JsonObject root = new JsonParser()
                    .parse(response.body().string()).getAsJsonObject();
                JsonObject data = root.getAsJsonObject("data");
                if (data == null || !data.has(String.valueOf(itemId))) return -1;

                JsonObject entry = data.getAsJsonObject(String.valueOf(itemId));
                long high = entry.has("high") ? entry.get("high").getAsLong() : -1;
                long low  = entry.has("low")  ? entry.get("low").getAsLong()  : -1;

                long price;
                if (high > 0 && low > 0) {
                    price = (high + low) / 2;
                } else if (high > 0) {
                    price = high;
                } else {
                    price = low;
                }

                if (price > 0) cache.put(itemId, price);
                return price;
            }
        } catch (Exception e) {
            log.warn("Could not fetch price for item {}: {}", itemId, e.getMessage());
            return -1;
        }
    }
}

package com.osr.jei.service;

import com.osr.jei.model.EquipmentStats;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses equipment bonuses ({@code {{Infobox Bonuses}}}) and item weight
 * ({@code {{Infobox Item|weight=}}}) from wikitext that {@link RecipeService}
 * already fetches and caches.
 *
 * <p><b>Zero extra network calls.</b>  By the time the panel calls
 * {@code getStats(itemName)}, {@code RecipeService.getRecipe(itemName)} will
 * already have populated the shared wikitext cache — this service just parses
 * the cached string.
 *
 * <p>Network errors and items with no {@code {{Infobox Bonuses}}} both return
 * {@code Optional.empty()}.  Results are cached per item name.
 */
@Slf4j
@Singleton
public class EquipmentService {

    @Inject private RecipeService recipeService;

    /** absent = never checked; empty Optional = no Infobox Bonuses on page. */
    private final ConcurrentHashMap<String, Optional<EquipmentStats>> statsCache =
        new ConcurrentHashMap<>();

    /** Weight in kg; {@code Double.NaN} = not found or item has no weight field. */
    private final ConcurrentHashMap<String, Double> weightCache =
        new ConcurrentHashMap<>();

    // ── Public API ─────────────────────────────────────────────────────────────

    /**
     * Returns the equipment stats for {@code itemName}, or empty if the item's
     * wiki page has no {@code {{Infobox Bonuses}}} template.
     */
    public Optional<EquipmentStats> getStats(String itemName) {
        String key = itemName.toLowerCase(Locale.ROOT);
        Optional<EquipmentStats> cached = statsCache.get(key);
        if (cached != null) return cached;

        try {
            String wikitext = recipeService.getWikitext(itemName);
            Optional<EquipmentStats> result = parseStats(wikitext);
            statsCache.put(key, result);

            // Parse weight from the same wikitext while we have it
            weightCache.put(key, parseWeight(wikitext));

            log.debug("[JEI] EquipmentStats for '{}': {}", itemName,
                result.isPresent() ? "found (slot=" + result.get().slot + ")" : "none");
            return result;

        } catch (Exception e) {
            log.warn("[JEI] EquipmentService failed for '{}': {}", itemName, e.getMessage());
            return Optional.empty(); // NOT cached — will retry
        }
    }

    /**
     * Returns the item weight in kg, or {@link Double#NaN} if unavailable.
     *
     * <p>This is always populated as a side-effect of {@link #getStats}, so
     * call that first.  If you call this before {@code getStats} it will
     * trigger a parse automatically (still zero extra network calls).
     */
    public double getWeight(String itemName) {
        String key = itemName.toLowerCase(Locale.ROOT);
        Double cached = weightCache.get(key);
        if (cached != null) return cached;

        // Trigger full parse — populates weightCache as a side effect
        getStats(itemName);
        return weightCache.getOrDefault(key, Double.NaN);
    }

    // ── Wikitext parsing ───────────────────────────────────────────────────────

    private Optional<EquipmentStats> parseStats(String wikitext) {
        if (wikitext == null || wikitext.isEmpty()) return Optional.empty();

        String lower = wikitext.toLowerCase(Locale.ROOT);
        int idx = lower.indexOf("{{infobox bonuses");
        if (idx < 0) return Optional.empty();

        String block = extractTemplateBlock(wikitext, idx);
        if (block == null) return Optional.empty();

        Map<String, String> p = parseParams(block);

        int astab  = signedInt(p.getOrDefault("astab",  "0"));
        int aslash = signedInt(p.getOrDefault("aslash", "0"));
        int acrush = signedInt(p.getOrDefault("acrush", "0"));
        int amagic = signedInt(p.getOrDefault("amagic", "0"));
        int arange = signedInt(p.getOrDefault("arange", "0"));
        int dstab  = signedInt(p.getOrDefault("dstab",  "0"));
        int dslash = signedInt(p.getOrDefault("dslash", "0"));
        int dcrush = signedInt(p.getOrDefault("dcrush", "0"));
        int dmagic = signedInt(p.getOrDefault("dmagic", "0"));
        int drange = signedInt(p.getOrDefault("drange", "0"));
        int str    = signedInt(p.getOrDefault("str",    "0"));
        int rstr   = signedInt(p.getOrDefault("rstr",   "0"));
        // mdmg may be "1%" or "+1%" — strip non-numeric prefix/suffix
        int mdmg   = signedInt(stripPercent(p.getOrDefault("mdmg", "0")));
        int prayer = signedInt(p.getOrDefault("prayer", "0"));
        String slot = clean(p.getOrDefault("slot", ""));
        int speed  = firstPositiveInt(p.getOrDefault("aspeed",
                        p.getOrDefault("speed", "0")));

        // A page can include a bare {{Infobox Bonuses}} with all zeros
        // (e.g. clothing items).  Include it only if the slot is named.
        if (slot.isEmpty()) return Optional.empty();

        return Optional.of(new EquipmentStats(
            astab, aslash, acrush, amagic, arange,
            dstab, dslash, dcrush, dmagic, drange,
            str, rstr, mdmg, prayer, slot, speed));
    }

    private double parseWeight(String wikitext) {
        if (wikitext == null || wikitext.isEmpty()) return Double.NaN;

        String lower = wikitext.toLowerCase(Locale.ROOT);
        // {{Infobox Item}} (or {{Infobox item}}) holds the weight field
        int idx = lower.indexOf("{{infobox item");
        if (idx < 0) return Double.NaN;

        String block = extractTemplateBlock(wikitext, idx);
        if (block == null) return Double.NaN;

        Map<String, String> p = parseParams(block);
        String raw = clean(p.getOrDefault("weight", ""));
        if (raw.isEmpty() || raw.equals("0")) return 0.0;

        try {
            return Double.parseDouble(raw.replace(",", "."));
        } catch (NumberFormatException e) {
            return Double.NaN;
        }
    }

    // ── Wikitext template utilities ────────────────────────────────────────────

    private String extractTemplateBlock(String text, int startIdx) {
        int depth = 0, i = startIdx;
        while (i < text.length() - 1) {
            char c = text.charAt(i), nx = text.charAt(i + 1);
            if      (c == '{' && nx == '{') { depth++; i += 2; }
            else if (c == '}' && nx == '}') {
                depth--;
                if (depth == 0) return text.substring(startIdx, i + 2);
                i += 2;
            } else { i++; }
        }
        return null;
    }

    private List<String> splitTopLevel(String text) {
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (i + 1 < text.length()) {
                char nx = text.charAt(i + 1);
                if ((c == '{' && nx == '{') || (c == '[' && nx == '[')) { depth++; i++; continue; }
                if ((c == '}' && nx == '}') || (c == ']' && nx == ']')) { depth--; i++; continue; }
            }
            if (c == '|' && depth == 0) { parts.add(text.substring(start, i)); start = i + 1; }
        }
        parts.add(text.substring(start));
        return parts;
    }

    private Map<String, String> parseParams(String block) {
        String inner = block;
        if (inner.startsWith("{{")) inner = inner.substring(2);
        if (inner.endsWith("}}"))   inner = inner.substring(0, inner.length() - 2);

        Map<String, String> params = new LinkedHashMap<>();
        List<String> parts = splitTopLevel(inner);
        for (int i = 1; i < parts.size(); i++) {
            String part = parts.get(i).replace("\n", " ").trim();
            if (part.isEmpty()) continue;
            int eq = part.indexOf('=');
            if (eq <= 0) continue;
            String key = part.substring(0, eq).trim().toLowerCase(Locale.ROOT);
            String val = part.substring(eq + 1).trim();
            if (!key.isEmpty()) params.put(key, val);
        }
        return params;
    }

    // ── Wiki markup stripping ──────────────────────────────────────────────────

    private static final Pattern WIKILINK  = Pattern.compile("\\[\\[(?:[^|\\]]*\\|)?([^\\]]+)\\]\\]");
    private static final Pattern TEMPLATE1 = Pattern.compile("\\{\\{[^{}|]*\\|([^{}|]*)\\}\\}");
    private static final Pattern TEMPLATE2 = Pattern.compile("\\{\\{[^{}]*\\}\\}");
    private static final Pattern HTML_TAG  = Pattern.compile("<[^>]+>");

    private String clean(String text) {
        if (text == null || text.trim().isEmpty()) return "";
        text = WIKILINK.matcher(text).replaceAll("$1");
        text = TEMPLATE1.matcher(text).replaceAll("$1");
        text = TEMPLATE2.matcher(text).replaceAll("");
        text = text.replaceAll("'{2,}", "");
        text = text.replace("&amp;", "&").replace("&lt;", "<")
                   .replace("&gt;", ">").replace("&nbsp;", " ").replace("&#160;", " ");
        text = HTML_TAG.matcher(text).replaceAll("");
        return text.replaceAll("\\s+", " ").trim();
    }

    // ── Number helpers ─────────────────────────────────────────────────────────

    private static final Pattern SIGNED_INT = Pattern.compile("[+-]?\\d+");
    private static final Pattern DIGITS     = Pattern.compile("\\d+");

    /**
     * Parses the first signed integer from a wikitext value string.
     * Handles leading +/-, trailing garbage (units, wiki templates).
     */
    private int signedInt(String raw) {
        if (raw == null || raw.isEmpty()) return 0;
        // Strip wiki markup first
        String cleaned = clean(raw);
        Matcher m = SIGNED_INT.matcher(cleaned.replace(",", ""));
        return m.find() ? Integer.parseInt(m.group()) : 0;
    }

    private int firstPositiveInt(String raw) {
        if (raw == null || raw.isEmpty()) return 0;
        Matcher m = DIGITS.matcher(raw.replace(",", ""));
        return m.find() ? Integer.parseInt(m.group()) : 0;
    }

    private String stripPercent(String s) {
        return s == null ? "0" : s.replace("%", "").trim();
    }
}

package com.osr.jei.service;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.osr.jei.model.MonsterInfo;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.net.URLEncoder;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Fetches monster location data from the OSRS Wiki.
 *
 * <p>One API call per unique monster (cached forever after first lookup):
 * wikitext ({@code prop=wikitext}) parsed for combat level via
 * {@code {{Infobox Monster}}} and location names via {@code {{LocLine}}} blocks.
 */
@Slf4j
@Singleton
public class MonsterService {

    private static final String WIKI_API   = "https://oldschool.runescape.wiki/api.php";
    private static final String USER_AGENT = "osrs-jei-plugin";

    @Inject private OkHttpClient okHttpClient;

    /** absent = never fetched; empty Optional = fetched, no useful data found. */
    private final ConcurrentHashMap<String, Optional<MonsterInfo>> cache =
        new ConcurrentHashMap<>();

    // ── Public API ─────────────────────────────────────────────────────────────

    public Optional<MonsterInfo> getMonsterInfo(String monsterName) {
        String key = monsterName.toLowerCase(Locale.ROOT);
        Optional<MonsterInfo> cached = cache.get(key);
        if (cached != null) return cached;

        try {
            Optional<MonsterInfo> result = fetchAndParse(monsterName);
            cache.put(key, result);
            return result;
        } catch (Exception e) {
            log.warn("[JEI] Monster info fetch failed for '{}': {}", monsterName, e.getMessage());
            return Optional.empty();
        }
    }

    // ── Network ────────────────────────────────────────────────────────────────

    @SuppressWarnings("deprecation")
    private Optional<MonsterInfo> fetchAndParse(String monsterName) throws Exception {
        String encoded = URLEncoder.encode(monsterName.replace(" ", "_"), "UTF-8");

        JsonObject wikitextRoot = fetchJson(WIKI_API
            + "?action=parse&prop=wikitext&format=json&redirects=true&page=" + encoded);
        if (wikitextRoot == null || !wikitextRoot.has("parse")) return Optional.empty();

        String wikitext = wikitextRoot.getAsJsonObject("parse")
            .getAsJsonObject("wikitext").get("*").getAsString();

        int          combat    = parseCombatLevel(wikitext);
        List<String> locations = parseLocLines(wikitext);

        log.debug("[JEI] Monster '{}': combat={} locations={}", monsterName, combat, locations);

        if (locations.isEmpty() && combat == 0) return Optional.empty();

        return Optional.of(new MonsterInfo(monsterName, combat, locations));
    }

    private JsonObject fetchJson(String urlStr) throws Exception {
        Request request = new Request.Builder()
            .url(urlStr)
            .header("User-Agent", USER_AGENT)
            .build();

        try (Response response = okHttpClient.newCall(request).execute()) {
            if (!response.isSuccessful() || response.body() == null) return null;
            return new JsonParser().parse(response.body().string()).getAsJsonObject();
        }
    }

    // ── Wikitext parsing ───────────────────────────────────────────────────────

    private int parseCombatLevel(String wikitext) {
        String lower = wikitext.toLowerCase(Locale.ROOT);
        int idx = lower.indexOf("{{infobox monster");
        if (idx < 0) return 0;
        String block = extractTemplateBlock(wikitext, idx);
        if (block == null) return 0;
        Map<String, String> params = parseParams(block);
        return firstInt(clean(coalesce(params, "combat1", "combat", "combat2")));
    }

    private List<String> parseLocLines(String wikitext) {
        Set<String> seen = new LinkedHashSet<>();
        String lower = wikitext.toLowerCase(Locale.ROOT);
        int pos = 0;
        while (true) {
            int idx = lower.indexOf("{{locline", pos);
            if (idx < 0) break;
            String block = extractTemplateBlock(wikitext, idx);
            if (block == null) { pos = idx + 9; continue; }
            Map<String, String> params = parseParams(block);
            String location = clean(params.getOrDefault("location", ""));
            if (!location.isEmpty()
                    && !location.equalsIgnoreCase("none")
                    && !location.equalsIgnoreCase("n/a")) {
                seen.add(location);
            }
            pos = idx + block.length();
        }
        return new ArrayList<>(seen);
    }

    // ── Wikitext template utilities ────────────────────────────────────────────

    private String extractTemplateBlock(String text, int startIdx) {
        int depth = 0, i = startIdx;
        while (i < text.length() - 1) {
            char c = text.charAt(i), next = text.charAt(i + 1);
            if      (c == '{' && next == '{') { depth++; i += 2; }
            else if (c == '}' && next == '}') {
                depth--;
                if (depth == 0) return text.substring(startIdx, i + 2);
                i += 2;
            } else { i++; }
        }
        return null;
    }

    private List<String> splitTopLevel(String text) {
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (i + 1 < text.length()) {
                char nx = text.charAt(i + 1);
                if ((c == '{' && nx == '{') || (c == '[' && nx == '[')) { depth++; i++; continue; }
                if ((c == '}' && nx == '}') || (c == ']' && nx == ']')) { depth--; i++; continue; }
            }
            if (c == '|' && depth == 0) { parts.add(text.substring(start, i)); start = i + 1; }
        }
        parts.add(text.substring(start));
        return parts;
    }

    private Map<String, String> parseParams(String block) {
        String inner = block;
        if (inner.startsWith("{{")) inner = inner.substring(2);
        if (inner.endsWith("}}"))   inner = inner.substring(0, inner.length() - 2);
        Map<String, String> params = new LinkedHashMap<>();
        List<String> parts = splitTopLevel(inner);
        for (int i = 1; i < parts.size(); i++) {
            String part = parts.get(i).replace("\n", " ").trim();
            if (part.isEmpty()) continue;
            int eq = part.indexOf('=');
            if (eq <= 0) continue;
            String key = part.substring(0, eq).trim().toLowerCase(Locale.ROOT);
            String val = part.substring(eq + 1).trim();
            if (!key.isEmpty()) params.put(key, val);
        }
        return params;
    }

    private String coalesce(Map<String, String> params, String... keys) {
        for (String key : keys) {
            String v = params.get(key);
            if (v != null && !v.trim().isEmpty()) return v;
        }
        return "";
    }

    // ── Wiki markup stripping ──────────────────────────────────────────────────

    private static final Pattern WIKILINK  = Pattern.compile("\\[\\[(?:[^|\\]]*\\|)?([^\\]]+)\\]\\]");
    private static final Pattern TEMPLATE1 = Pattern.compile("\\{\\{[^{}|]*\\|([^{}|]*)\\}\\}");
    private static final Pattern TEMPLATE2 = Pattern.compile("\\{\\{[^{}]*\\}\\}");
    private static final Pattern HTML_TAG  = Pattern.compile("<[^>]+>");

    private String clean(String text) {
        if (text == null || text.trim().isEmpty()) return "";
        text = WIKILINK.matcher(text).replaceAll("$1");
        text = TEMPLATE1.matcher(text).replaceAll("$1");
        text = TEMPLATE2.matcher(text).replaceAll("");
        text = text.replaceAll("'{2,}", "");
        text = text.replace("&amp;", "&").replace("&lt;", "<")
                   .replace("&gt;", ">").replace("&nbsp;", " ").replace("&#160;", " ");
        text = HTML_TAG.matcher(text).replaceAll("");
        return text.replaceAll("\\s+", " ").trim();
    }

    private static final Pattern DIGITS = Pattern.compile("\\d+");

    private int firstInt(String text) {
        if (text == null || text.isEmpty()) return 0;
        Matcher m = DIGITS.matcher(text.replace(",", ""));
        return m.find() ? Integer.parseInt(m.group()) : 0;
    }
}

package com.osr.jei;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;

/**
 * Entry point for the OSRS JEI plugin.
 *
 * This plugin adds a sidebar panel to RuneLite where you can:
 *   - Search any OSRS item by name
 *   - See its Grand Exchange price
 *   - See every monster that drops it (with rates)
 *   - Open the OSRS Wiki page for full details
 *
 * Right-clicking any item in the game (inventory, bank, equipment, ground)
 * shows a "JEI Lookup" option that jumps straight to that item's detail page
 * in the sidebar.
 */
@Slf4j
@PluginDescriptor(
    name        = "OSRS JEI",
    description = "Browse items, drop tables, and sources — inspired by JEI from Minecraft",
    tags        = {"item", "drops", "wiki", "browser", "search", "jei"}
)
public class JEIPlugin extends Plugin {

    @Inject private Client        client;
    @Inject private ClientToolbar clientToolbar;
    @Inject private JEIPanel      panel;

    private NavigationButton navButton;

    @Override
    protected void startUp() {
        // Build the Swing UI on the Event Dispatch Thread (required by Java Swing)
        SwingUtilities.invokeLater(() -> {
            try {
                panel.init();

                navButton = NavigationButton.builder()
                    .tooltip("OSRS JEI — Item Browser")
                    .icon(createIcon())
                    .priority(6)
                    .panel(panel)
                    .build();

                clientToolbar.addNavigation(navButton);
                log.info("OSRS JEI plugin started successfully");
            } catch (Exception e) {
                // Without this catch, Swing swallows the error silently — you'd never know it failed
                log.error("OSRS JEI failed to start", e);
            }
        });
    }

    @Override
    protected void shutDown() {
        SwingUtilities.invokeLater(() -> {
            clientToolbar.removeNavigation(navButton);
            log.info("OSRS JEI plugin stopped");
        });
    }

    // ── Right-click item lookup ────────────────────────────────────────────────

    /**
     * Adds a "JEI Lookup" entry to the right-click menu whenever an item's
     * "Examine" option is present — i.e. when the player right-clicks an item
     * in their inventory, bank, equipment, or on the ground.
     *
     * Clicking the entry selects the JEI sidebar panel and loads that item's
     * detail page (price, recipe, drop sources, wiki link).
     */
    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        int type = event.getType();

        // Fire on item Examine — inventory items and items on the ground.
        // (Bank items use widget-based menus with a different action type and
        // cannot be intercepted the same way without widget inspection.)
        if (type != MenuAction.EXAMINE_ITEM.getId()
                && type != MenuAction.EXAMINE_ITEM_GROUND.getId()) {
            return;
        }

        final int itemId = event.getIdentifier();

        // Insert our entry just above "Examine" (position -1 = last slot)
        client.createMenuEntry(-1)
            .setOption("<col=ff9040>JEI</col> Lookup")
            .setTarget(event.getTarget())           // keeps the coloured item name
            .setType(MenuAction.RUNELITE)
            .onClick(e -> SwingUtilities.invokeLater(() -> {
                // Open the JEI sidebar panel, then load the item detail
                clientToolbar.openPanel(navButton);
                panel.lookupItem(itemId);
            }));
    }

    // ── Config ─────────────────────────────────────────────────────────────────

    @Provides
    JEIConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(JEIConfig.class);
    }

    // ── Icon ───────────────────────────────────────────────────────────────────

    /**
     * Draws a simple 16x16 icon for the navigation button.
     * It's a golden square with "JEI" — replace with a real PNG later if you want.
     */
    private BufferedImage createIcon() {
        BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();

        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        // OSRS gold-ish background
        g.setColor(new Color(200, 160, 50));
        g.fillRoundRect(0, 0, 15, 15, 4, 4);

        // Dark border
        g.setColor(new Color(80, 60, 10));
        g.drawRoundRect(0, 0, 15, 15, 4, 4);

        // Label
        g.setColor(Color.BLACK);
        g.setFont(new Font("Arial", Font.BOLD, 7));
        g.drawString("JEI", 2, 10);

        g.dispose();
        return img;
    }
}
